cypress_script:
describe('Login Functionality', () => {
  it('should log in with valid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[placeholder="Email Address"]').type('valid@example.com');
    cy.get('input[placeholder="Password"]').type('validPassword');
    cy.get('button.btn.btn-default').contains('Login').click();
    cy.url().should('not.include', '/login');
  });
  it('should not log in with empty credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('button.btn.btn-default').contains('Login').click();
    cy.url().should('include', '/login');
    cy.get('section#form').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Functionality', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[placeholder="Email Address"]', 'valid@example.com');
    await page.fill('input[placeholder="Password"]', 'validPassword');
    await page.click('button.btn.btn-default');
    await expect(page).toHaveURL(/^(?!.*\/login).*/);
  });
  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.click('button.btn.btn-default');
    await expect(page).toHaveURL(/.*\/login/);
    await expect(page.locator('section#form')).toBeVisible();
  });
});
